/* Connected local source, reading and evidence workflow. */
(()=>{
 'use strict';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const project=()=>window.REIWorkbench?.getProject();
 const prefs=new Map(),selections=new Map();let selected=new Set();
 function preference(){const id=project()?.id;if(!prefs.has(id))prefs.set(id,{query:'',status:'',compact:false,evidenceQuery:'',source:''});return prefs.get(id)}
 function rememberSource(id,projectId){const destination=projectId||project()?.id;if(!destination)return;try{sessionStorage.setItem('rei-reader-source-'+destination,id)}catch{}}
 function readerLink(id,text='Read & capture'){return `<a class="text-link" href="#research/${esc(project().id)}/reader" data-read-source="${esc(id)}">${text}</a>`}
 function filterLibrary(){const p=project(),pref=preference();let count=0;document.querySelectorAll('.paper-record').forEach((el,i)=>{const paper=p.papers[i];el.hidden=!(el.dataset.search.includes(pref.query.toLowerCase())&&(!pref.status||paper.status===pref.status));if(!el.hidden)count++});document.querySelector('#paper-no-results').hidden=count>0;document.querySelector('#library-count').textContent=`${count} of ${p.papers.length} sources`;document.querySelector('#paper-list').classList.toggle('library-compact',pref.compact)}
 function library(){const p=project(),pref=preference(),filter=document.querySelector('.research-filter');if(!filter)return;
 filter.insertAdjacentHTML('beforeend',`<label>Reading status filter<select id="library-status"><option value="">All reading statuses</option>${['To read','Reading','Read'].map(s=>`<option>${s}</option>`).join('')}</select></label><button type="button" class="button secondary" id="library-density" aria-pressed="${pref.compact}">Compact sources</button><p id="library-count" role="status" aria-live="polite"></p>`);
 const query=document.querySelector('#paper-filter');query.value=pref.query;document.querySelector('#library-status').value=pref.status;
 document.querySelectorAll('.paper-record').forEach((el,i)=>{const paper=p.papers[i],note=el.querySelector('.paper-note');if(note){const details=document.createElement('details');details.className='source-reading-note';details.innerHTML='<summary>Reading notes</summary>';note.before(details);details.append(note);if(paper.notes)details.open=true}el.querySelector('.paper-actions').insertAdjacentHTML('afterbegin',readerLink(paper.id));const count=p.evidence.filter(n=>n.paperId===paper.id).length;el.querySelector('h3').insertAdjacentHTML('afterend',`<p class="source-trail">${count} evidence ${count===1?'note':'notes'} recorded</p>`)});
 filterLibrary();
 }
 function reader(){const p=project(),select=document.querySelector('#wb-reader-source');if(!select)return;let id;try{id=sessionStorage.getItem('rei-reader-source-'+p.id)}catch{}if(p.papers.some(s=>s.id===id)){select.value=id;select.dispatchEvent(new Event('change',{bubbles:true}))}
 const form=document.querySelector('[data-wb-form=passage]');form.insertAdjacentHTML('afterbegin',`<input type="hidden" name="captureSource" value=""><p id="capture-source" class="capture-context"></p><p class="wb-hint">Capture the exact words, then explain what they mean. Check the original PDF before saving.</p>`);form.querySelector('[name=quote]').closest('label').insertAdjacentHTML('afterend','<label>Passage PDF page<input name="capturePage" type="number" min="1" step="1" value="1" required></label>');form.insertAdjacentHTML('beforeend',`<p id="capture-feedback" role="status" aria-live="polite"></p><a class="text-link" href="#research/${esc(p.id)}/evidence">Review saved evidence</a>`);updateCaptureSource();
 }
 function updateCaptureSource(){const select=document.querySelector('#wb-reader-source'),el=document.querySelector('#capture-source');if(el&&select)el.textContent='Capturing from: '+(project().papers.find(p=>p.id===select.value)?.title||'Choose a source')}
 function filterEvidence(){const p=project(),pref=preference();let count=0;const matching=new Set(p.evidence.filter(n=>(!pref.source||n.paperId===pref.source)&&[n.quote,n.findings,n.method,n.context,n.limitations,n.relevance,p.papers.find(s=>s.id===n.paperId)?.title].join(' ').toLowerCase().includes(pref.evidenceQuery.toLowerCase())).map(n=>n.id));document.querySelectorAll('.evidence-record').forEach((el,i)=>{el.hidden=!matching.has(p.evidence[i].id);if(!el.hidden)count++});document.querySelectorAll('.evidence-table tbody tr').forEach((el,i)=>el.hidden=!matching.has(p.evidence[i].id));document.querySelector('#evidence-count').textContent=`${count} of ${p.evidence.length} evidence notes`;document.querySelector('#evidence-no-results').hidden=count>0;}
 function selectionState(){const count=selected.size;document.querySelector('#compare-evidence').disabled=count!==2;document.querySelector('#compare-count').textContent=`${count} of 2 selected`;document.querySelectorAll('[data-compare-note]').forEach(el=>{el.checked=selected.has(el.dataset.compareNote);el.disabled=count>=2&&!el.checked});}
 function evidence(){const p=project(),pref=preference();if(!p.evidence.length||!document.querySelector('.evidence-records'))return;if(!selections.has(p.id))selections.set(p.id,new Set());selected=selections.get(p.id);for(const id of selected)if(!p.evidence.some(n=>n.id===id))selected.delete(id);const table=document.querySelector('.evidence-table-wrap');table.insertAdjacentHTML('beforebegin',`<div class="evidence-tools"><label>Find evidence<input id="evidence-query" type="search" placeholder="Finding, passage, method or source"></label><label>Filter evidence by source<select id="evidence-source"><option value="">All sources</option>${p.papers.map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')}</select></label><p id="evidence-count" role="status" aria-live="polite"></p></div><div class="evidence-selection"><p id="compare-count" role="status">0 of 2 selected</p><button type="button" class="button secondary" id="compare-evidence" disabled>Compare selected notes</button><button type="button" class="text-button" id="compare-clear">Clear selection</button></div><section id="evidence-comparison" class="evidence-comparison" hidden></section><p id="evidence-no-results" hidden>No evidence matches these filters. Clear the search or choose another source.</p>`);
 document.querySelector('#evidence-query').value=pref.evidenceQuery;document.querySelector('#evidence-source').value=pref.source;
 document.querySelectorAll('.evidence-record').forEach((el,i)=>{const n=p.evidence[i],links=p.workbench.claims.filter(c=>c.links.some(l=>l.evidenceId===n.id)).length;el.querySelector('.eyebrow')?.remove();el.insertAdjacentHTML('afterbegin',`<label class="evidence-pick"><input type="checkbox" data-compare-note="${esc(n.id)}" > Select E${i+1} for comparison</label><p class="source-trail">${links} linked ${links===1?'claim':'claims'} · ${esc(n.locator||'Location not recorded')}</p>`);el.querySelector('.actions').insertAdjacentHTML('beforeend',readerLink(n.paperId,'Return to source'))});filterEvidence();selectionState();
 }
 function compare(){const p=project(),notes=[...selected].map(id=>p.evidence.find(n=>n.id===id));if(notes.length!==2||notes.some(n=>!n))return;const panel=document.querySelector('#evidence-comparison');panel.hidden=false;panel.innerHTML=`<h3 tabindex="-1">Compare the evidence</h3><p>Consider differences in population, method and limitations before explaining agreement or disagreement.</p><div class="comparison-pair">${notes.map(n=>`<article><h4>${esc(p.papers.find(s=>s.id===n.paperId)?.title)}</h4><dl>${[['quote','Exact passage'],['findings','Finding'],['method','Method'],['context','Population / context'],['limitations','Limitations'],['locator','Source location']].map(([key,label])=>`<div><dt>${label}</dt><dd>${esc(n[key]||'Not recorded')}</dd></div>`).join('')}</dl></article>`).join('')}</div><form id="evidence-compare-form"><label>Your comparison<textarea name="explanation" rows="4" maxlength="20000" required placeholder="What agrees, what differs, and what might explain it?"></textarea></label><div class="actions"><button class="button primary">Save comparison</button><button type="button" class="text-button" id="compare-close">Close comparison</button></div><p id="comparison-status" role="status" aria-live="polite">Saved comparisons will appear in Synthesis matrix.</p></form>`;panel.dataset.left=notes[0].id;panel.dataset.right=notes[1].id;panel.querySelector('h3').focus();}
 function synthesisComparisons(){const p=project();if(!document.querySelector('.wb-synthesis-table')||!p.workbench.comparisons.length)return;document.querySelector('.research-content').insertAdjacentHTML('beforeend',`<section class="wb-section"><h3>Saved evidence comparisons</h3><p>Your explanations stay linked to the original evidence notes.</p>${p.workbench.comparisons.map(c=>`<article class="wb-record"><h4>${[c.left,c.right].map(id=>esc(p.papers.find(s=>s.id===p.evidence.find(n=>n.id===id)?.paperId)?.title||'Source unavailable')).join(' / ')}</h4><p>${esc(c.explanation)}</p><a class="text-link" href="#research/${esc(p.id)}/evidence">Review the evidence</a></article>`).join('')}</section>`)}
  function claimRooms(){const p=project(),records=[...document.querySelectorAll('.research-content article[id^="claim-"]')];if(!records.length)return;
 const heading=document.querySelector('.research-content .research-section-label');heading.insertAdjacentHTML('afterend','<div class="claim-tools"><label>Find a claim<input id="claim-search" type="search" placeholder="Statement, source or finding"></label><label>Claim evidence filter<select id="claim-filter"><option value="all">All claims</option><option value="unlinked">No evidence linked</option><option value="challenged">With challenging evidence</option><option value="reviewed">Marked reviewed</option></select></label><p id="claim-count" role="status" aria-live="polite"></p></div>');
 records.forEach(el=>{const c=p.workbench.claims.find(c=>el.id==='claim-'+c.id);if(!c)return;const counts=['supports','challenges','mixed','uncertain'].map(r=>c.links.filter(l=>l.relation===r).length);el.querySelector('h3').insertAdjacentHTML('afterend',`<p class="claim-evidence-summary">${counts.map((n,i)=>n+' '+['supporting','challenging','mixed','uncertain'][i]).join(' · ')}</p><p class="wb-hint">${c.links.length?'Review the passages and boundaries before relying on this claim.':'This interpretation has no recorded evidence links yet.'} “Reviewed” is your own status, not scientific approval.</p>`);
 el.dataset.claimSearch=[c.text,...c.links.map(l=>{const n=p.evidence.find(n=>n.id===l.evidenceId);return [n?.findings,p.papers.find(s=>s.id===n?.paperId)?.title].join(' ')})].join(' ').toLowerCase();
 el.querySelectorAll('.wb-links > li').forEach((li,i)=>{const n=p.evidence.find(n=>n.id===c.links[i]?.evidenceId);if(!n)return;li.insertAdjacentHTML('beforeend',`<details class="claim-trace"><summary>Inspect passage and limitations</summary><dl>${[['quote','Exact passage'],['method','Method'],['context','Population / context'],['limitations','Limitations'],['transferability','Boundaries'],['locator','Source location']].map(([key,label])=>`<div><dt>${label}</dt><dd>${esc(n[key]||'Not recorded')}</dd></div>`).join('')}</dl><div class="actions"><a class="text-link" href="#research/${esc(p.id)}/evidence" data-focus-evidence="${esc(n.id)}">Open this evidence note</a>${readerLink(n.paperId,'Read original source')}</div></details>`)});
 });filterClaims();
 }
 function filterClaims(){const p=project(),query=document.querySelector('#claim-search')?.value.toLowerCase()||'',type=document.querySelector('#claim-filter')?.value||'all';let visible=0;document.querySelectorAll('.research-content article[id^="claim-"]').forEach(el=>{const c=p.workbench.claims.find(c=>el.id==='claim-'+c.id);const match=type==='all'||type==='unlinked'&&!c.links.length||type==='challenged'&&c.links.some(l=>l.relation==='challenges')||type==='reviewed'&&c.status==='Reviewed';el.hidden=!match||!el.dataset.claimSearch.includes(query);if(!el.hidden)visible++});document.querySelector('#claim-count').textContent=visible+' of '+p.workbench.claims.length+' claims';}
 let focusedEvidence='';
 function focusEvidence(){if(!focusedEvidence)return;const p=project(),index=p.evidence.findIndex(n=>n.id===focusedEvidence),record=document.querySelectorAll('.evidence-record')[index];if(!record)return;const pref=preference();pref.source='';pref.evidenceQuery='';document.querySelector('#evidence-query').value='';document.querySelector('#evidence-source').value='';filterEvidence();record.tabIndex=-1;setTimeout(()=>{if(!record.isConnected)return;record.focus();record.scrollIntoView({block:'center',behavior:'instant'})},0);focusedEvidence='';}
 document.addEventListener('input',ev=>{if(ev.target.id==='claim-search')filterClaims()});
 document.addEventListener('change',ev=>{if(ev.target.id==='claim-filter')filterClaims()});
 document.addEventListener('click',ev=>{const link=ev.target.closest('[data-focus-evidence]');if(link)focusedEvidence=link.dataset.focusEvidence});
 addEventListener('rei:research-render',()=>{if(!project())return;library();reader();evidence();synthesisComparisons();claimRooms();focusEvidence()});
 document.addEventListener('input',ev=>{if(ev.target.name==='quote'){const f=ev.target.closest('form');if(f?.elements.captureSource){f.elements.captureSource.value=document.querySelector('#wb-reader-source').value;f.dispatchEvent(new Event('input',{bubbles:true}));}}if(ev.target.id==='paper-filter'){preference().query=ev.target.value;filterLibrary()}if(ev.target.id==='evidence-query'){preference().evidenceQuery=ev.target.value;filterEvidence()}});
 document.addEventListener('change',ev=>{if(ev.target.id==='library-status'){preference().status=ev.target.value;filterLibrary()}if(ev.target.dataset.reading)filterLibrary();if(ev.target.id==='evidence-source'){preference().source=ev.target.value;filterEvidence()}if(ev.target.dataset.compareNote){ev.target.checked?selected.add(ev.target.dataset.compareNote):selected.delete(ev.target.dataset.compareNote);selectionState()}if(ev.target.id==='wb-reader-source'){rememberSource(ev.target.value);updateCaptureSource();const f=document.querySelector('[data-wb-form=passage]');if(f?.elements.quote.value){const feedback=document.querySelector('#capture-feedback');if(feedback)feedback.textContent='Your passage draft is retained. Return to its original source or capture a new passage before saving.';}}});
 document.addEventListener('click',ev=>{const a=ev.target.closest('[data-read-source]');if(a)rememberSource(a.dataset.readSource,a.dataset.readProject);const b=ev.target.closest('button');if(!b)return;if(b.id==='library-density'){const pref=preference();pref.compact=!pref.compact;b.setAttribute('aria-pressed',pref.compact);filterLibrary()}if(b.id==='compare-evidence')compare();if(b.id==='compare-close'){document.querySelector('#evidence-comparison').hidden=true;document.querySelector('#compare-evidence').focus()}if(b.id==='compare-clear'){selected.clear();document.querySelectorAll('[data-compare-note]').forEach(el=>el.checked=false);selectionState();document.querySelector('#evidence-comparison').hidden=true}});
 document.addEventListener('submit',async ev=>{if(ev.target.id!=='evidence-compare-form')return;ev.preventDefault();const p=project(),panel=document.querySelector('#evidence-comparison'),text=ev.target.elements.explanation.value.trim(),status=document.querySelector('#comparison-status'),b=ev.target.querySelector('button');if(!text){status.textContent='Write your comparison before saving.';return}const record={id:crypto.randomUUID(),left:panel.dataset.left,right:panel.dataset.right,explanation:text};b.disabled=true;p.workbench.comparisons.push(record);try{await window.REIWorkbench.saveProject();status.textContent='Comparison saved on this device. Open Synthesis matrix to review it.';ev.target.elements.explanation.readOnly=true;b.textContent='Comparison saved'}catch{p.workbench.comparisons=p.workbench.comparisons.filter(c=>c.id!==record.id);status.textContent='Could not save. Your text is still here; retry before leaving.';b.disabled=false}});
})();
